mapper.select:
SELECT *
FROM lunaerp_production_color_instruction
WHERE id = #{id}
  AND deleted = 1
  AND status = 'PENDING'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_production_color_instruction
SET deleted = 0,
    status = 'PENDING',
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1
  AND status = 'PENDING'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_color_instruction
WHERE id = #{id}
  AND deleted = 1
  AND status = 'PENDING'
  AND tenant_id = #{tenantId}
